choose.when:

  ${key_vault_uri}secrets/cath-service-api-client-id/?api-version=7.0
  GET



  ${key_vault_uri}secrets/cath-service-api-client-secret/?api-version=7.0
  GET



  ${key_vault_uri}secrets/cath-service-api-client-scope/?api-version=7.0
  GET



  https://login.microsoftonline.com/${tenant_id}/oauth2/v2.0/token
  POST

    application/x-www-form-urlencoded

  @{
    var clientId = ((IResponse)context.Variables["clientIdResponse"]).Body.As()["value"].ToString();
    var secret = ((IResponse)context.Variables["clientSecretResponse"]).Body.As()["value"].ToString();
    var scope = ((IResponse)context.Variables["scopeResponse"]).Body.As()["value"].ToString();
    return "grant_type=client_credentials&client_id=" + clientId
      + "&scope=" + System.Net.WebUtility.UrlEncode(scope + "/.default")
      + "&client_secret=" + System.Net.WebUtility.UrlEncode(secret);
  }

<set-variable name="cathAuthToken" value="@("Bearer " + (string)((IResponse)context.Variables["tokenResponse"]).Body.As()["access_token"])" />
